corrected_code:
def get_consignment_tracking(request, consignment_id):
    consignment = get_object_or_404(
        Consignment.objects.select_related('order__customer__payment_profile', 'destination_warehouse'),
        id=consignment_id,
        order__customer=request.user
    )
    return JsonResponse({
        'status': consignment.status,
        'customer_name': consignment.order.customer.full_name,
        'shipping_address': consignment.order.shipping_address,
        'billing_card_last4': consignment.order.customer.payment_profile.card_last4
    })
